<script>
 let {settings,api,guarded,busy=false,onchange,onsave,operatorSetup=null}=$props();
 let accountKey=$state(''),enableUserPlay=$state(false),accountStatus=$state(null);
 const account=$derived((accountStatus||operatorSetup)?.accounts?.find(a=>a.provider===provider));
 async function saveAccount(){accountStatus=await api({intent:'operator',command:{intent:'configure',provider,key:accountKey,enableUserPlay}});accountKey='';notice='Account saved for this server session. No validation or generation call was made.';}
 async function disconnectAccount(){accountStatus=await api({intent:'operator',command:{intent:'disconnect',provider}});accountKey='';notice='Provider account disconnected for this server session.';}
 async function useProfile(){const next=structuredClone($state.snapshot(settings));next.mode='provider';next.selection={gm:profileId,npc:profileId,assistant:profileId};onchange(next);await onsave();notice='Provider profile selected for play and authoring. Set a per-turn cost budget below before paid generation.';}
 let profileId=$state(''),provider=$state('openrouter'),profileName=$state('OpenRouter'),model=$state(''),custom=$state(false),query=$state(''),catalog=$state({status:'idle',models:[]}),cacheMode=$state('provider-default'),ttl=$state('5m'),billingAcknowledged=$state(false),notice=$state('');let requestVersion=0;
 const filtered=$derived(catalog.models.filter(row=>(row.id+' '+row.name+' '+row.description).toLowerCase().includes(query.toLowerCase())).slice(0,300));
 const selected=$derived(catalog.models.find(row=>row.id===model)),saved=$derived(settings.profiles.find(p=>p.id===profileId)),claude=$derived(/^(anthropic\/)?claude(?:[-/]|$)/i.test(model));
 const value=n=>n===null||n===undefined?'Unknown':String(n),price=n=>n===null||n===undefined?'Unknown':'$'+n+' / million tokens';
 function resetProvider(){requestVersion++;catalog={status:'idle',models:[]};query='';model='';custom=false;cacheMode='provider-default';billingAcknowledged=false;profileName=provider==='nanogpt'?'NanoGPT':'OpenRouter';notice='';}
 function editProfile(id){profileId=id;requestVersion++;catalog={status:'idle',models:[]};query='';notice='';const profile=settings.profiles.find(p=>p.id===id);if(!profile){provider='openrouter';resetProvider();return;}provider=['openrouter','nanogpt'].includes(profile.providerType)?profile.providerType:'openrouter';profileName=profile.name;model=profile.model;custom=true;cacheMode=profile.promptCache?.mode||'provider-default';ttl=profile.promptCache?.ttl||'5m';billingAcknowledged=profile.promptCache?.billingAcknowledged||false;}
 async function discover(){const version=++requestVersion,source=provider;catalog={...catalog,status:'loading'};notice='';try{const result=await api({intent:'models',catalog:{provider:source,refresh:true}});if(version!==requestVersion||source!==provider)return;catalog=result;if(result.models.some(row=>row.id===model))custom=false;}catch(error){if(version!==requestVersion)return;catalog={...catalog,status:catalog.models.length?'stale':'error',error:{message:error.message}};}}
 function pickModel(){custom=false;cacheMode='provider-default';billingAcknowledged=false;notice='';}
 async function saveProfile(){if(!model.trim())throw Error('Choose a catalog model or enter an exact custom ID.');if(model.length>200)throw Error('Model ID exceeds 200 characters.');if(cacheMode==='claude-explicit'&&(!claude||provider==='nanogpt'&&!billingAcknowledged))throw Error('Explicit Claude caching needs its supported model and NanoGPT billing acknowledgment.');const metadata=!custom?selected:null,old=settings.profiles.find(p=>p.id===profileId),id=old?.providerType===provider?old.id:'provider_'+crypto.randomUUID().replaceAll('-',''),hosts={openrouter:'https://openrouter.ai/api/v1',nanogpt:'https://api.nano-gpt.com/api/v1'},profile={id,name:profileName.trim()||provider,providerType:provider,baseUrl:hosts[provider],model:model.trim(),credentialRef:operatorSetup?.available?'operator_'+provider:old?.providerType===provider?old.credentialRef:null,contextWindowTokens:metadata?.contextTokens?Math.min(200000,metadata.contextTokens):old?.providerType===provider&&old.model===model?old.contextWindowTokens:null,inputUsdPerMillion:metadata?.pricing.input??(old?.providerType===provider&&old.model===model?old.inputUsdPerMillion:null),outputUsdPerMillion:metadata?.pricing.output??(old?.providerType===provider&&old.model===model?old.outputUsdPerMillion:null),priceSource:metadata&&metadata.pricing.input!==null&&metadata.pricing.output!==null?'verified-catalog':old?.providerType===provider&&old.model===model?old.priceSource:'simulation',promptCache:{mode:cacheMode,ttl,billingAcknowledged:provider==='nanogpt'&&cacheMode==='claude-explicit'?billingAcknowledged:false},...(metadata?{catalogMeta:{source:metadata.source,fetchedAt:catalog.fetchedAt,contextTokens:metadata.contextTokens,maxOutputTokens:metadata.maxOutputTokens,capabilities:metadata.capabilities,cacheReadUsdPerMillion:metadata.pricing.cacheRead,cacheWriteUsdPerMillion:metadata.pricing.cacheWrite}}:{})};const next=structuredClone($state.snapshot(settings));const index=next.profiles.findIndex(p=>p.id===id);if(index<0){if(next.profiles.length>=12)throw Error('At most twelve provider profiles are supported.');next.profiles.push(profile);}else next.profiles[index]=profile;onchange(next);await onsave();profileId=id;notice='Provider profile saved. Choose its routing below; saving never enables dispatch.';}
</script>
<section class="provider-settings" aria-label="API and model settings">
 <h3>API and model settings</h3><label for="api-profile">Saved profile</label><select id="api-profile" value={profileId} onchange={event=>editProfile(event.currentTarget.value)}><option value="">New provider profile</option>{#each settings.profiles.filter(p=>['openrouter','nanogpt'].includes(p.providerType)) as profile}<option value={profile.id}>{profile.name} · {profile.model}</option>{/each}</select>
 <div class="provider-row"><label>Provider<select id="api-provider" bind:value={provider} onchange={resetProvider}><option value="openrouter">OpenRouter</option><option value="nanogpt">NanoGPT</option></select></label><button id="api-get-models" disabled={busy||catalog.status==='loading'} onclick={discover}>{catalog.status==='loading'?'Getting models…':catalog.models.length?'Refresh models':'Get models'}</button></div>
 {#if operatorSetup?.available}<section aria-label="Provider account"><h3>Connect your account</h3><p>{account?.configured?'Account connected':'Account not connected'} · {account?.enabled?'User-initiated provider play enabled':'Provider play disabled'}</p><label for="api-session-key">{provider==='openrouter'?'OpenRouter':'NanoGPT'} API key</label><input id="api-session-key" type="password" autocomplete="new-password" bind:value={accountKey}/><label class="check"><input id="api-enable-user-play" type="checkbox" bind:checked={enableUserPlay}/>Enable user-initiated play with this account and the saved budgets</label><button id="api-connect-account" disabled={busy||!accountKey.trim()} onclick={()=>guarded(saveAccount)}>Connect account for this session</button>{#if account?.configured}<button id="api-disconnect-account" disabled={busy} onclick={()=>guarded(disconnectAccount)}>Disconnect account</button>{/if}<p class="small">The key stays in this server's memory and is forgotten on restart. It is not saved to campaign files, instructions, journals or this device. Connecting makes no provider call. Generation begins only when you submit a turn or agent request.</p></section>{/if}
 <p class="host">{provider==='openrouter'?'openrouter.ai/api/v1':'api.nano-gpt.com/api/v1'} · server-side metadata lookup</p>
 {#if catalog.status==='loading'}<p role="status">Loading model metadata…</p>{:else if ['error','stale'].includes(catalog.status)}<p role="alert">{catalog.status==='stale'?'Saved catalog is stale. ':''}{catalog.error?.message}</p>{:else if catalog.status==='empty'}<p role="status">This catalog is empty. Retry or enter an exact custom model ID.</p>{/if}
 <label for="api-model-search">Search models</label><input id="api-model-search" type="search" bind:value={query} placeholder="Search name or exact model ID"/>
 <label for="api-model-select">Model</label><select id="api-model-select" value={custom?'':model} onchange={event=>{model=event.currentTarget.value;pickModel();}}><option value="">Choose a model</option>{#if model&&!custom&&!filtered.some(row=>row.id===model)}<option value={model}>{model} · selected</option>{/if}{#each filtered as row}<option value={row.id}>{row.name} · {row.id}</option>{/each}</select><p class="small">{filtered.length} shown of {catalog.models.length}. {catalog.status==='idle'?'Get the catalog to see available models.':'Catalog access does not validate a key or account billing.'}</p>
 <label class="check"><input id="api-custom-toggle" type="checkbox" bind:checked={custom} onchange={()=>{if(custom){cacheMode='provider-default';billingAcknowledged=false;}}}/>Use an exact custom or saved model ID</label>{#if custom}<label for="api-custom-model">Exact model ID</label><input id="api-custom-model" bind:value={model} maxlength="200" placeholder="provider/model-id"/>{/if}
 {#if selected&&!custom}<dl class="metadata"><dt>Context</dt><dd>{value(selected.contextTokens)} tokens</dd><dt>Output limit</dt><dd>{value(selected.maxOutputTokens)} tokens</dd><dt>Input / output</dt><dd>{price(selected.pricing.input)} / {price(selected.pricing.output)}</dd><dt>Cache read / write</dt><dd>{price(selected.pricing.cacheRead)} / {price(selected.pricing.cacheWrite)}</dd>{#each Object.entries(selected.capabilities) as [name,capability]}<dt>{name}</dt><dd>{capability===null?'Unknown':capability?'Supported':'Unsupported'}</dd>{/each}</dl>{#if selected.pricing.conditional}<p>Conditional provider/model pricing may apply.</p>{/if}{:else}<p class="small">Custom model metadata and pricing are unknown until verified. Unknown values never grant a dispatch budget.</p>{/if}
 <label for="api-profile-name">Profile name</label><input id="api-profile-name" bind:value={profileName} maxlength="100"/>
 <label for="api-cache-mode">Prompt caching</label><select id="api-cache-mode" bind:value={cacheMode} onchange={()=>billingAcknowledged=false}><option value="provider-default">Provider default / implicit when eligible</option><option value="claude-explicit" disabled={!claude}>Explicit Claude prefix caching — opt in</option></select>
 {#if cacheMode==='claude-explicit'}<label for="api-cache-ttl">Claude cache TTL</label><select id="api-cache-ttl" bind:value={ttl}><option value="5m">5 minutes</option><option value="1h">1 hour — route pricing may differ</option></select>{#if provider==='nanogpt'}<p class="billing-warning">NanoGPT explicit Claude caching uses pay-as-you-go and bypasses subscription coverage.</p><label class="check"><input id="api-cache-billing" type="checkbox" bind:checked={billingAcknowledged}/>I explicitly accept that billing change for this profile.</label>{/if}{/if}
 <p class="small">Reusable system/tools and conversation prefixes are versioned and scoped to campaign, actor, provider and model. Changing turn context follows reusable dialogue. Hits and savings depend on the actual route; response caching is off.</p>
 <button id="api-save-profile" disabled={busy||!model.trim()||cacheMode==='claude-explicit'&&(!claude||provider==='nanogpt'&&!billingAcknowledged)} onclick={()=>guarded(saveProfile)}>Save provider profile</button>{#if operatorSetup?.available&&profileId}<button id="api-use-profile" disabled={busy} onclick={()=>guarded(useProfile)}>Use this profile for play and authoring</button>{/if}{#if notice}<p role="status">{notice}</p>{/if}
</section>
<style>.provider-settings{border:1px solid #46533e;border-radius:10px;padding:16px;margin:16px 0;background:#141d14;min-width:0}.provider-row{display:flex;gap:12px;align-items:end}.provider-row label{flex:1;margin-bottom:0}.provider-row button{flex-shrink:0;min-height:44px}label{display:block;margin:12px 0 5px;font-size:13px}input:not([type=checkbox]),select{display:block;width:100%;box-sizing:border-box;min-height:44px;padding:9px;font:inherit;background:#101510;color:#eee3c9;border:1px solid #46533e;border-radius:6px}button{min-height:44px;border:1px solid #b89d65;border-radius:6px;padding:8px 13px;background:#364330;color:#eee3c9}.host,.small{font-size:12px;color:#a4ad99;overflow-wrap:anywhere}.metadata{display:grid;grid-template-columns:minmax(100px,1fr) minmax(0,2fr);gap:6px;font-size:13px;overflow-wrap:anywhere}.metadata dt{color:#a4ad99}.metadata dd{margin:0}.check{display:flex;gap:9px;align-items:center;min-height:44px}.billing-warning{border-left:3px solid #c6a66c;padding:8px 12px;background:#2a2517}h3{font:20px Georgia,serif}button:disabled{opacity:.45}@media(max-width:650px){.provider-settings{padding:12px}.provider-row{gap:8px}.provider-row button{font-size:13px}input:not([type=checkbox]),select{font-size:16px}.metadata{grid-template-columns:1fr 1.4fr}button{font-size:14px}}</style>
